/**
 * Templates: categories (e.g. Plumbers, Restaurants), the templates generated by the AI for each
 * category (saved and reused by any project) and the template chosen by a project.
 *
 * Generating a template does not save it: the UI shows the result, then saves it (possibly after
 * a few regenerations) with POST /template-categories/:cid/templates.
 *
 * Before its first template, a category is analyzed by the AI (industry.js): business, customers,
 * design conventions of the industry, recommended Home sections and suitable design directions.
 * The analysis is saved on the category and used by every template generation.
 *
 * Users (lib/owner.js): categories are shared; a template belongs to the user who saved it, who can
 * share it with everyone. Templates saved before users existed (no owner) are shared.
 */
import { Router } from 'express';
import { all, get, run, parseJson } from '../db/index.js';
import { badRequest, notFound, HttpError, LANGUAGES } from '../lib/util.js';
import { createProvider } from '../ai/registry.js';
import { AIError } from '../ai/AIProvider.js';
import { COLOR_KEYS, FONTS, ICONS, LAYOUTS, SPACINGS, STYLE_OPTIONS, WEIGHTS, sanitizeSpec } from '../templates/spec.js';
import { compareTemplates, directionById, directionList, diversify } from '../templates/directions.js';
import { generateTemplateSpec } from '../templates/generate.js';
import { analyzeCategory, sanitizeProfile } from '../templates/industry.js';
import { touch } from './projects.js';
import { canEditTemplate, canUseTemplate, forbidden, requireOwnProvider } from '../lib/owner.js';

const router = Router();

const CATEGORIES_SQL = `
  SELECT c.*,
    (SELECT COUNT(*) FROM site_templates t WHERE t.category_id = c.id) AS template_count,
    (SELECT COUNT(*) FROM projects p JOIN site_templates t ON t.id = p.template_id WHERE t.category_id = c.id) AS project_count
  FROM template_categories c ORDER BY c.name COLLATE NOCASE`;

const TEMPLATES_SQL = `
  SELECT t.*, c.name AS category_name, (SELECT COUNT(*) FROM projects p WHERE p.template_id = t.id) AS used_by
  FROM site_templates t JOIN template_categories c ON c.id = t.category_id`;

/** Category row -> API object (the industry analysis parsed, or null). */
function serializeCategory(row) {
  const { profile_json, ...rest } = row;
  const raw = parseJson(profile_json, null);
  return { ...rest, profile: raw ? { ...sanitizeProfile(raw), analyzed_at: raw.analyzed_at || null, analyzed_by: raw.analyzed_by || '' } : null };
}
const listCategories = () => all(CATEGORIES_SQL).map(serializeCategory);
const categoryById = (id) => listCategories().find((c) => c.id === Number(id));

/** Ask the AI for the industry analysis of a category and save it. */
async function analyzeAndSave(provider, row, cat) {
  const { profile, tokens } = await analyzeCategory(provider, cat);
  const stored = { ...profile, analyzed_at: new Date().toISOString(), analyzed_by: `${row.name} · ${row.model}` };
  run('UPDATE template_categories SET profile_json = ? WHERE id = ?', JSON.stringify(stored), cat.id);
  return { profile: stored, tokens };
}

const requireProvider = (id, user) => requireOwnProvider(id, user);

const requireCategory = (id) => {
  const row = get('SELECT * FROM template_categories WHERE id = ?', id);
  if (!row) throw notFound('Category');
  return row;
};

/** Template row -> API object. can_edit: the user may change, share or delete it. */
function serializeTemplate(row, user = null) {
  const { spec_json, ...rest } = row;
  const spec = sanitizeSpec(parseJson(spec_json, {}));
  return {
    ...rest,
    owner: row.owner || null,
    shared: row.owner == null || row.shared === 1,
    can_edit: canEditTemplate(row, user),
    spec,
    direction_name: directionById(spec.direction)?.name || '',
  };
}

/** Template the user may see (404 otherwise); { edit: true }: the user must be allowed to change it. */
const requireTemplate = (id, user = null, { edit = false } = {}) => {
  const row = get(`${TEMPLATES_SQL} WHERE t.id = ?`, id);
  if (!canUseTemplate(row, user)) throw notFound('Template');
  if (edit && !canEditTemplate(row, user)) throw forbidden('template');
  return serializeTemplate(row, user);
};

/** Category name: trimmed, non-empty, unique (case-insensitive). */
function categoryName(value, exceptId = null) {
  const name = String(value ?? '').trim().slice(0, 80);
  if (!name) throw badRequest('Enter a category name.');
  if (get('SELECT id FROM template_categories WHERE name = ? AND id IS NOT ?', name, exceptId)) throw badRequest(`The category "${name}" already exists.`);
  return name;
}

function templateName(value) {
  const name = String(value ?? '').trim().slice(0, 120);
  if (!name) throw badRequest('Enter a template name.');
  return name;
}

const language = (value) => (LANGUAGES[value] ? value : 'it');

/** Allowed values of a template spec (for the template editor). */
router.get('/template-options', (req, res) =>
  res.json({ fonts: FONTS, icons: ICONS, layouts: LAYOUTS, styleOptions: STYLE_OPTIONS, spacings: SPACINGS, weights: WEIGHTS, colorKeys: COLOR_KEYS, directions: directionList() })
);

// ---------------------------------------------------------------- categories --

router.get('/template-categories', (req, res) => res.json(listCategories()));

router.post('/template-categories', (req, res) => {
  const description = String(req.body?.description ?? '').trim().slice(0, 1000);
  const { lastInsertRowid } = run('INSERT INTO template_categories (name, description) VALUES (?, ?)', categoryName(req.body?.name), description);
  res.status(201).json(categoryById(lastInsertRowid));
});

router.patch('/template-categories/:cid', (req, res) => {
  const cat = requireCategory(req.params.cid);
  const name = req.body?.name !== undefined ? categoryName(req.body.name, cat.id) : cat.name;
  const description = req.body?.description !== undefined ? String(req.body.description).trim().slice(0, 1000) : cat.description;
  // A new name or description changes the business: the industry analysis must be done again
  const changed = name !== cat.name || description !== cat.description;
  run('UPDATE template_categories SET name = ?, description = ?, profile_json = CASE WHEN ? THEN NULL ELSE profile_json END WHERE id = ?', name, description, changed ? 1 : 0, cat.id);
  res.json(categoryById(cat.id));
});

/** (Re)run the industry analysis of the category. Body: { providerId } -> category (with its profile) + tokens */
router.post('/template-categories/:cid/analyze', async (req, res) => {
  const cat = requireCategory(req.params.cid);
  const row = requireProvider(req.body?.providerId, req.user);
  try {
    const { tokens } = await analyzeAndSave(createProvider(row), row, cat);
    res.json({ ...categoryById(cat.id), tokens });
  } catch (err) {
    if (err instanceof AIError) throw new HttpError(502, err.message);
    throw err;
  }
});

/** Delete a category and its templates. Projects that used them must choose another template. */
router.delete('/template-categories/:cid', (req, res) => {
  const cat = requireCategory(req.params.cid);
  const others = all('SELECT owner FROM site_templates WHERE category_id = ?', cat.id).filter((t) => !canEditTemplate(t, req.user));
  if (others.length) throw new HttpError(403, 'This category contains templates of other users: it cannot be deleted.');
  run('DELETE FROM template_categories WHERE id = ?', cat.id);
  res.status(204).end();
});

/**
 * Generate a template for the category with the AI (not saved). The category is analyzed first if it
 * has no industry analysis yet. Its design direction (among the ones suitable for the industry),
 * fonts, look, layouts and optional sections are chosen to differ as much as possible from the
 * saved templates of the category.
 * Body: { providerId, instructions?, language?, direction? (id, else automatic),
 *         exclude? (directions of discarded drafts), avoidColors? (their primary colors) }
 * -> { spec, tokens, generated_by, direction: { id, name, summary }, profile, analyzed }
 */
router.post('/template-categories/:cid/templates/generate', async (req, res) => {
  const cat = requireCategory(req.params.cid);
  const row = requireProvider(req.body?.providerId, req.user);
  const provider = createProvider(row);
  try {
    let profile = serializeCategory(cat).profile;
    let analysisTokens = 0;
    if (!profile) ({ profile, tokens: analysisTokens } = await analyzeAndSave(provider, row, cat));
    const existing = all('SELECT name, spec_json FROM site_templates WHERE category_id = ? ORDER BY id', cat.id).map((t) => ({ name: t.name, ...sanitizeSpec(parseJson(t.spec_json, {})) }));
    // Templates of the other categories (latest 80): the new one also differs from the rest of the library
    const library = all('SELECT spec_json FROM site_templates WHERE category_id != ? ORDER BY id DESC LIMIT 80', cat.id).map((t) => sanitizeSpec(parseJson(t.spec_json, {})));
    const list = (v, max) => (Array.isArray(v) ? v.map(String).slice(0, max) : []);
    const { spec, tokens, direction } = await generateTemplateSpec(provider, {
      category: cat,
      instructions: String(req.body?.instructions ?? '').slice(0, 2000),
      language: language(req.body?.language),
      existing,
      direction: String(req.body?.direction ?? ''),
      exclude: list(req.body?.exclude, 20),
      avoidColors: list(req.body?.avoidColors, 20).filter((c) => /^#[0-9a-f]{6}$/i.test(c)),
      profile,
      library,
    });
    res.json({
      spec,
      tokens: tokens + analysisTokens,
      generated_by: `${row.name} · ${row.model}`,
      direction: { id: direction.id, name: direction.name, summary: direction.summary },
      profile,
      analyzed: analysisTokens > 0,
    });
  } catch (err) {
    if (err instanceof AIError) throw new HttpError(502, err.message);
    throw err;
  }
});

/**
 * How alike the templates of the category are (the ones the user can see), pair by pair:
 * -> { pairs: [{ a, b (template ids), likeness (0..100), shared: [what they visibly have in common] }] }
 */
router.get('/template-categories/:cid/compare', (req, res) => {
  const cat = requireCategory(req.params.cid);
  const templates = all(`${TEMPLATES_SQL} WHERE t.category_id = ? ORDER BY t.id`, cat.id)
    .filter((r) => canUseTemplate(r, req.user))
    .map((r) => serializeTemplate(r, req.user));
  const pairs = [];
  for (let i = 0; i < templates.length; i++)
    for (let j = i + 1; j < templates.length; j++) pairs.push({ a: templates[i].id, b: templates[j].id, ...compareTemplates(templates[i].spec, templates[j].spec) });
  res.json({ pairs });
});

/** Save a template in the category, owned by the user. Body: { name, spec, shared?, instructions?, language?, generated_by?, tokens_used? } */
router.post('/template-categories/:cid/templates', (req, res) => {
  const cat = requireCategory(req.params.cid);
  const b = req.body || {};
  if (!b.spec || typeof b.spec !== 'object') throw badRequest('Generate the template first.');
  const { lastInsertRowid } = run(
    'INSERT INTO site_templates (owner, shared, category_id, name, instructions, language, spec_json, generated_by, tokens_used) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
    req.user,
    b.shared ? 1 : 0,
    cat.id,
    templateName(b.name),
    String(b.instructions ?? '').slice(0, 2000),
    language(b.language),
    JSON.stringify(sanitizeSpec(b.spec)),
    String(b.generated_by ?? '').slice(0, 200),
    Math.max(0, Math.round(Number(b.tokens_used) || 0))
  );
  res.status(201).json(requireTemplate(lastInsertRowid, req.user));
});

// ----------------------------------------------------------------- templates --

/** The templates the user can see (own + shared), or the ones of a category (?category=<id>). */
router.get('/templates', (req, res) => {
  const rows = req.query.category
    ? all(`${TEMPLATES_SQL} WHERE t.category_id = ? ORDER BY t.id DESC`, Number(req.query.category))
    : all(`${TEMPLATES_SQL} ORDER BY c.name COLLATE NOCASE, t.id DESC`);
  res.json(rows.filter((r) => canUseTemplate(r, req.user)).map((r) => serializeTemplate(r, req.user)));
});

/** A template; ?project=<id>: also another user's private template when that (shared) project uses it (read-only). */
router.get('/templates/:tid', (req, res) => {
  const project = req.query.project ? get('SELECT template_id FROM projects WHERE id = ?', Number(req.query.project)) : null;
  if (project && project.template_id === Number(req.params.tid)) {
    const row = get(`${TEMPLATES_SQL} WHERE t.id = ?`, project.template_id);
    if (row) return res.json(serializeTemplate(row, req.user));
  }
  res.json(requireTemplate(req.params.tid, req.user));
});

/** Rename, edit the design (colors, fonts, layouts, texts), move to another category or share it (owner only). */
router.patch('/templates/:tid', (req, res) => {
  const tpl = requireTemplate(req.params.tid, req.user, { edit: true });
  const b = req.body || {};
  if (b.shared !== undefined) run('UPDATE site_templates SET shared = ? WHERE id = ?', b.shared ? 1 : 0, tpl.id);
  const name = b.name !== undefined ? templateName(b.name) : tpl.name;
  const spec = b.spec && typeof b.spec === 'object' ? sanitizeSpec(b.spec) : tpl.spec;
  const categoryId = b.category_id !== undefined ? requireCategory(Number(b.category_id)).id : tpl.category_id;
  run("UPDATE site_templates SET name = ?, spec_json = ?, category_id = ?, updated_at = datetime('now') WHERE id = ?", name, JSON.stringify(spec), categoryId, tpl.id);
  res.json(requireTemplate(tpl.id, req.user));
});

/**
 * "Make it more different": a new design (not saved) for the template, as different as possible from
 * the other templates of its category, keeping palette, texts and Home sections (directions.js).
 * Body: { spec? (the design being edited, else the saved one) } -> { spec, direction: { id, name } }
 */
router.post('/templates/:tid/diversify', (req, res) => {
  const tpl = requireTemplate(req.params.tid, req.user, { edit: true });
  const spec = req.body?.spec && typeof req.body.spec === 'object' ? sanitizeSpec(req.body.spec) : tpl.spec;
  const others = all('SELECT spec_json FROM site_templates WHERE category_id = ? AND id != ? ORDER BY id', tpl.category_id, tpl.id).map((t) => sanitizeSpec(parseJson(t.spec_json, {})));
  const library = all('SELECT spec_json FROM site_templates WHERE category_id != ? ORDER BY id DESC LIMIT 80', tpl.category_id).map((t) => sanitizeSpec(parseJson(t.spec_json, {})));
  const suitable = serializeCategory(requireCategory(tpl.category_id)).profile?.directions || null;
  const next = sanitizeSpec(diversify(spec, others, { library, suitable }));
  const direction = directionById(next.direction);
  res.json({ spec: next, direction: { id: direction.id, name: direction.name } });
});

/** Copy of a visible template, owned by the user (not shared). */
router.post('/templates/:tid/duplicate', (req, res) => {
  const tpl = requireTemplate(req.params.tid, req.user);
  const { lastInsertRowid } = run(
    'INSERT INTO site_templates (owner, category_id, name, instructions, language, spec_json, generated_by, tokens_used) VALUES (?, ?, ?, ?, ?, ?, ?, 0)',
    req.user,
    tpl.category_id,
    `${tpl.name} (copy)`.slice(0, 120),
    tpl.instructions,
    tpl.language,
    JSON.stringify(tpl.spec),
    tpl.generated_by
  );
  res.status(201).json(requireTemplate(lastInsertRowid, req.user));
});

/** Delete a template (owner only). Projects that used it must choose another one. */
router.delete('/templates/:tid', (req, res) => {
  const tpl = requireTemplate(req.params.tid, req.user, { edit: true });
  run('DELETE FROM site_templates WHERE id = ?', tpl.id);
  res.status(204).end();
});

// ------------------------------------------------------- project <-> template --

router.put('/projects/:id/template', (req, res) => {
  const project = get('SELECT * FROM projects WHERE id = ?', req.params.id);
  if (!project) throw notFound('Project');
  const templateId = req.body?.template_id ? requireTemplate(Number(req.body.template_id), req.user).id : null;
  // A category template replaces the Template Kit of the project
  if (templateId) run('UPDATE projects SET template_id = ?, template_kit_id = NULL WHERE id = ?', templateId, project.id);
  else run('UPDATE projects SET template_id = NULL WHERE id = ?', project.id);
  touch(project.id);
  res.json({ template_id: templateId });
});

export default router;
